<?php
declare(strict_types=1);namespace Haerriz\AgenticCommerce\Model\Resolver;
use Haerriz\AgenticCommerce\Model\Wishlist\WishlistService;use Haerriz\AgenticCommerce\Model\GraphQl\CustomerContext;use Haerriz\AgenticCommerce\Model\GraphQl\IdempotentExecutor;use Magento\Framework\Exception\{AuthorizationException,LocalizedException};use Magento\Framework\GraphQl\Config\Element\Field;use Magento\Framework\GraphQl\Exception\{GraphQlAuthorizationException,GraphQlInputException};use Magento\Framework\GraphQl\Query\ResolverInterface;use Magento\Framework\GraphQl\Schema\Type\ResolveInfo;
class AddToWishlistResolver implements ResolverInterface{public function __construct(private WishlistService $service,private CustomerContext $customerContext,private IdempotentExecutor $idempotency){}public function resolve(Field $field,$context,ResolveInfo $info,array $value=null,array $args=null){$i=(array)($args['input']??[]);$sku=trim((string)($i['sku']??''));if($sku==='')throw new GraphQlInputException(__('SKU is required.'));$identity=$this->customerContext->identityForTool($context,$i['client_id']??null,'add_product_to_wishlist');try{return$this->idempotency->execute('add_product_to_wishlist',$i,$identity,fn():array=>$this->service->add($identity,$sku));}catch(AuthorizationException $e){throw new GraphQlAuthorizationException(__($e->getMessage()));}catch(LocalizedException $e){throw new GraphQlInputException(__($e->getMessage()));}}}
